def apply(inputs, premises):
    service_covered = inputs["service_type"] == premises["covered_service_type"] and inputs["service_place"] in premises["covered_places"]
    threshold_met = False
    for amount, year in zip(inputs["domestic_service_payment_amounts"], inputs["payment_years"]):
        for offset in premises["year_offsets"]:
            if year == inputs["query_year"] - offset and amount >= premises["cash_payment_threshold"]:
                threshold_met = True
    section_applies = service_covered and not threshold_met
    if section_applies:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}
